'use strict';
// Offline support, generated by build.py. VERSION changes whenever any file changes,
// so a new deploy installs a fresh cache and deletes the old one.
const VERSION = 'ee99199d6ce8';
const PRECACHE = ["/app.css", "/app.js", "/core.js", "/ds.css", "/ds.js", "/favicon.svg", "/fonts/inter.woff2", "/fonts/jetbrains-mono.woff2", "/fonts/space-grotesk.woff2", "/icon-192.png", "/icon-512.png", "/", "/inspect.js"];
const CACHE = 'ov-' + VERSION;

self.addEventListener('install', e => {
  e.waitUntil(caches.open(CACHE).then(c => c.addAll(PRECACHE)).then(() => self.skipWaiting()));
});
self.addEventListener('activate', e => {
  e.waitUntil(caches.keys().then(ks => Promise.all(ks.filter(k => k !== CACHE).map(k => caches.delete(k)))).then(() => self.clients.claim()));
});
self.addEventListener('fetch', e => {
  const req = e.request, url = new URL(req.url);
  if (req.method !== 'GET' || url.origin !== location.origin) return;
  if (req.mode === 'navigate') {
    // pages: network first (always fresh online), cached copy offline
    e.respondWith(fetch(req).then(r => { const c = r.clone(); caches.open(CACHE).then(k => k.put(url.pathname, c)); return r; })
      .catch(() => caches.match(url.pathname).then(r => r || caches.match('/'))));
    return;
  }
  // files: cache first (they are versioned by this worker), then network
  e.respondWith(caches.match(req, { ignoreSearch: true }).then(r => r || fetch(req)));
});
